import React, {useContext} from 'react'
import './CSS/ShopCategory.css'
import {ShopContext} from '../Context/Context'
import dropdown_icon from '../Components/Assets/dropdown_icon.png'
import Item from '../Components/items/Item'

const ShopCategory = (props) => {
    const {all_product} = useContext(ShopContext);
    return(
        <div className='shop-category'>
            <img className='shopcategory-banner' src={props.banner} alt="" />
            <div className="shopcategory-indexsort">
                <p> 
                    <span>Showing 1-12</span> out of 36 products
                </p>
                <div className="shopcategory-sort">
                    Sort by <img src={dropdown_icon} alt='' />
                </div>
            </div>
            <div className="shopcatergory-products">
                {all_product.map((item) => {
                    if(props.category===item.category) {return(<Item key={item.id} id={item.id} 
                        name={item.name} image={item.image} old_price={item.old_price} new_price={item.new_price} />
                      )}
                      else {
                        return null
                      }
                 })}
            </div>
            <div className="shopcatergory-loadmore">
                Explore More
            </div>
        </div>
    )
}

export default ShopCategory
